import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易闡真 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易闡真 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/chanzhen/041.md","filePath":"classics/chanzhen/041.md"}'),s={name:"classics/chanzhen/041.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：解，險以動，動而免乎險，解。解，利西南，往得眾也。其來複吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之時大矣哉！</p></blockquote><h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>初六：無咎。</p><p>九二：田獲三狐，得黃矢，貞吉。</p><p>六三：負且乘，致寇至。貞吝。</p><p>九四：解而拇，朋至斯孚。</p><p>六五：君子維有解，吉。有孚於小人。</p><p>上六：公用射隼於高墉之上，獲之，無不利。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雷雨作，解。君子以赦過宥罪。</p><p>解者，脫散也。上震雷，下坎水，是雷動雨降，雷雨作而陰陽氣通，解之象也。</p><p>君子有見於此，知修道者當陰氣結滯之時，須用武火以煅煉；及陽氣已復之時，宜用文火以溫養。各有其時，不得差遲。以是於陰氣解散以後，赦過宥罪，順其自然，使其自消自化，而無容強制也。人之有過有罪者，皆由順其後天，昧其先天，恣情縱欲，無所不至，此剋制之功不可缺。剋制者，改過消罪，以化氣質耳。及其氣質已化，先天來複，道心常存，人心不起，罪過已無，剋制之功無所用矣。赦之者，赦其已往之過也；宥之者，宥其從前之罪也。赦之宥之，正氣盛而邪氣自無，真者在而假者不來。否則，不知止足，猶以罪過為念，終是人心用事，既無過而又招過，既無罪而又引罪，解而又不解，陰險尚在，陽氣不純，所謂“卻除妄想重增病，趨向真如亦是差”者，是也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>解，佳買反。夙，音宿。拇，茂後反。隼音信。</p><p>解者，脫散之義。卦德上震動，下坎險，陽氣動而出險，險外之動，動之遂心，故謂解。此乘時採藥之卦，承上睽卦而來。睽者，陰陽不和，悅明不當，陰氣用事，陽氣有陷，此解脫陽氣之功不可缺。解脫陽氣者，採藥也。採藥貴乎知時，若不知時，當面錯過，陰氣仍在，陽氣又去，雖藥在咫尺，未許我得。</p><p>悟真雲：“鉛遇癸生須急採，金逢望後不堪嘗。”當其一陽生於坤地，先天之氣，自虛無中來，天地之心迴轉，所謂西南得朋，正鉛遇癸生，大藥發現，道心震動，人心安靜之時，此自然之解，吉之先見者也。是以解利西南，無所往，其來複，吉。無所往而來複，非人所勉強而然，乃一時自然之現露，出之於天。但天時已到，尤賴人力，急須下手扶陽抑陰，天人合發，藉此一點陽氣，復而又復，復於純陽無陰之地，道心常存，人心永滅，方是解去危難，縱橫逆順，無不如意，是以有攸往夙吉也。</p><p>夙者，早也。早則藥氣方生，屬於先天；遲則藥氣已過，屬於後天。藥氣方生而急採，則先天堅固而得吉；藥氣已過而始採，則後天又發而不吉。夙吉二字，大有深意，有不得不早者，所謂“若到一陽才動處，便宜進火莫延遲”者是也。</p><p>初六，居於至險之地，柔弱無能，不能自出，而知親近有道之士，借他人之智慧，以解自己之昏暗，有咎者亦能無咎。此柔而借剛解險者也。</p><p>九二，以一陽而居於二陰之內，剛而能柔，惟精惟一，允執厥中，既不使人心為惡，如田中獲狐，而不縱放其狐，又不求人心強滅，如得黃矢，而不傷害其狐。不縱不傷，順其所欲，漸次導之，使其自消自化，不解而解，解之而最吉者。此剛而用柔解險者也。</p><p>六三，愚而自用，妄想天寶，無道心而強制人心，以心制心，不但不能去人心，而且有以招人心。如負物者欲乘車，自致寇傷，雖解事屬正，然恃一己之陰，不求他家之陽，亦修道者取吝之事。此柔而強欲解險者也。</p><p>九四，剛而不正，又應初陰，道心中人心相雜，解陰而不果，如解而拇矣。夫解散人心，所以振道心也。人心解去於道心來至，信之解之，在拇能動不能行，可見人心惟危，道心惟微矣。此剛為柔牽、不解險者也。</p><p>六五，虛人心而求道心，是君子維有解也。道心為君子之心，人心為小人之心。道心之解與未解，可於人心驗之。人心化盡，方是道心之難解。若稍有一點人心，而道心之難猶未解去，故修道者必使宥密之中，而無絲毫滓質為極功。此點化群陰之解險者也。</p><p>上六，在解之終，一切客氣盡消，只有人心未死，此一點人心，貪圖無比，即罪之魁，如隼鳥棲於高墉，所當急須解去者。幸在解終，正氣盛而邪氣弱，以道心而解人心，直下斷絕，無不利者。此大公無私之解險者也。</p><p>然則解難出險之道，貴於知時，尤貴於剛柔相當，不先不後，不急不緩，乘時下手，未有不獲利者。然所以獲利處，總要知的西南坤位耳。</p><p>噫!藥出西南是坤位，欲尋坤位豈離人，分明說破君須記，只恐相逢認不真。西南坤位，豈易知哉!</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
